changeSet.sql:
DROP TABLE quote_edp_results;
CREATE TABLE quote_edp_results ( id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(), quote_id INT NOT NULL, journey VARCHAR(20) NOT NULL DEFAULT 'quote', edp_id INT NOT NULL, edp_name VARCHAR(255) NOT NULL, edp_start_date DATE NOT NULL, impact JSONB NOT NULL, catchments JSONB, levy_provisional_amount NUMERIC(12, 2) NOT NULL, levy_inflation_adjusted NUMERIC(12, 2) NOT NULL, levy_original_base_amount NUMERIC(12, 2) NOT NULL, levy_base_charge_per_unit NUMERIC(12, 2) NOT NULL, levy_original_base_charge_per_unit NUMERIC(12, 2) NOT NULL, levy_units INT NOT NULL, levy_model_version INT NOT NULL, levy_calculated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT fk_quote_edp_results_quote_id FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE, CONSTRAINT ck_quote_edp_results_journey CHECK (journey IN ('quote', 'request_to_use')), CONSTRAINT ck_quote_edp_results_catchments CHECK ( catchments IS NULL OR ( jsonb_typeof(catchments) = 'array' AND NOT jsonb_path_exists(catchments, 'strict $[*] ? (@.type() <> "object")') AND NOT jsonb_path_exists(catchments, 'lax $[*] ? ( !exists(@.label) || @.label.type() <> "string" || !exists(@.catchmentId) || (@.catchmentId.type() <> "string" && @.catchmentId.type() <> "null") || !exists(@.catchmentOverlapPercentage) || @.catchmentOverlapPercentage.type() <> "number" || @.catchmentOverlapPercentage < 0 || @.catchmentOverlapPercentage > 100)') ) ) );
-- The latest row for a quote and EDP is the current calculation CREATE INDEX ix_quote_edp_results_latest ON quote_edp_results (quote_id, edp_id, created_at DESC, id DESC);
